const errorPublico = (mensaje, codigo = 'CONFLICTO') => Object.assign(new Error(mensaje), { codigoPublico: codigo });
const nulo = (valor) => valor === '' || valor === undefined ? null : valor;
const redondear = (valor) => Math.round((Number(valor) + Number.EPSILON) * 100) / 100;

async function calcularDistanciaPorCalles(origen, destino) {
  if ([origen.latitud, origen.longitud, destino.latitud, destino.longitud].some((valor) => valor == null || !Number.isFinite(Number(valor)))) {
    throw errorPublico('No se pudo validar la ubicación del comercio o del domicilio');
  }
  const coordenadas = `${origen.longitud},${origen.latitud};${destino.longitud},${destino.latitud}`;
  try {
    const respuesta = await fetch(`https://router.project-osrm.org/route/v1/driving/${coordenadas}?overview=false&steps=false`, { signal: AbortSignal.timeout(12000) });
    if (!respuesta.ok) throw new Error('Servicio de rutas no disponible');
    const resultado = await respuesta.json();
    const ruta = resultado.code === 'Ok' ? resultado.routes?.[0] : null;
    if (!ruta) throw new Error('Ruta inexistente');
    return Number((Number(ruta.distance) / 1000).toFixed(1));
  } catch {
    throw errorPublico('No fue posible calcular el recorrido por calles. Volvé a intentarlo');
  }
}

export async function obtenerConfiguracion(publica = false) {
  const [[configuracion]] = await baseDatos.query('SELECT * FROM configuracion_ecommerce WHERE id = 1');
  const [[zonas], [franjas]] = await Promise.all([
    baseDatos.query('SELECT * FROM zonas_entrega ORDER BY localidad, distancia_desde_km'),
    baseDatos.query("SELECT id, nombre, TIME_FORMAT(hora_desde, '%H:%i') AS hora_desde, TIME_FORMAT(hora_hasta, '%H:%i') AS hora_hasta, capacidad_pedidos, dias_semana, esta_activa FROM franjas_entrega ORDER BY hora_desde"),
  ]);
  if (publica) delete configuracion.cuenta_mercado_pago_id;
  const [categorias] = publica ? await baseDatos.query(`SELECT DISTINCT c.id,c.nombre,c.icono_url FROM categorias c JOIN productos p ON p.categoria_id=c.id JOIN productos_ecommerce pe ON pe.producto_id=p.id AND pe.esta_publicado=TRUE WHERE c.esta_activa=TRUE ORDER BY c.nombre`) : [[]];
  return { configuracion, zonas: publica ? zonas.filter((zona) => zona.esta_activa) : zonas, franjas: publica ? franjas.filter((franja) => franja.esta_activa) : franjas, categorias };
}

export async function actualizarConfiguracion(datos) {
  const campos = ['nombre_tienda','esta_activa','direccion_origen','latitud_origen','longitud_origen','distancia_maxima_km','pedido_minimo','envio_gratis_desde','costo_envio_base','costo_por_km','minutos_reserva','permite_retiro','permite_envio','permite_efectivo','permite_transferencia','permite_mercado_pago','cuenta_mercado_pago_id','telefono_contacto','mensaje_portada'];
  await baseDatos.query(`UPDATE configuracion_ecommerce SET ${campos.map((campo) => `${campo} = ?`).join(', ')} WHERE id = 1`, campos.map((campo) => nulo(datos[campo])));
  return { id: 1 };
}

export async function guardarZona(id, datos) {
  if (datos.distancia_hasta_km <= datos.distancia_desde_km) throw errorPublico('La distancia final debe superar a la inicial');
  const valores = [datos.nombre, datos.localidad, nulo(datos.codigo_postal_patron), datos.distancia_desde_km, datos.distancia_hasta_km, datos.costo, nulo(datos.pedido_minimo), datos.esta_activa];
  if (id) { await baseDatos.query('UPDATE zonas_entrega SET nombre=?, localidad=?, codigo_postal_patron=?, distancia_desde_km=?, distancia_hasta_km=?, costo=?, pedido_minimo=?, esta_activa=? WHERE id=?', [...valores, id]); return { id }; }
  const [resultado] = await baseDatos.query('INSERT INTO zonas_entrega (nombre, localidad, codigo_postal_patron, distancia_desde_km, distancia_hasta_km, costo, pedido_minimo, esta_activa) VALUES (?, ?, ?, ?, ?, ?, ?, ?)', valores); return { id: resultado.insertId };
}

export async function guardarFranja(id, datos) {
  if (datos.hora_hasta <= datos.hora_desde) throw errorPublico('La hora final debe ser posterior a la inicial');
  const valores = [datos.nombre, datos.hora_desde, datos.hora_hasta, datos.capacidad_pedidos, datos.dias_semana, datos.esta_activa];
  if (id) { await baseDatos.query('UPDATE franjas_entrega SET nombre=?, hora_desde=?, hora_hasta=?, capacidad_pedidos=?, dias_semana=?, esta_activa=? WHERE id=?', [...valores, id]); return { id }; }
  const [resultado] = await baseDatos.query('INSERT INTO franjas_entrega (nombre, hora_desde, hora_hasta, capacidad_pedidos, dias_semana, esta_activa) VALUES (?, ?, ?, ?, ?, ?)', valores); return { id: resultado.insertId };
}

function condicionesProductos(consulta, admin = false) {
  const condiciones = ['p.esta_activo = TRUE']; const parametros = [];
  if (!admin || consulta.estado === 'publicados') condiciones.push('COALESCE(pe.esta_publicado, FALSE) = TRUE');
  if (admin && consulta.estado === 'ocultos') condiciones.push('COALESCE(pe.esta_publicado, FALSE) = FALSE');
  if (consulta.buscar) { const patron = `%${consulta.buscar}%`; condiciones.push('(p.nombre LIKE ? OR pe.nombre_online LIKE ? OR EXISTS (SELECT 1 FROM productos_codigos_barra pcb WHERE pcb.producto_id=p.id AND pcb.codigo_barra LIKE ?))'); parametros.push(patron, patron, patron); }
  if (consulta.categoria_id) { condiciones.push('p.categoria_id = ?'); parametros.push(consulta.categoria_id); }
  if (consulta.marca_id) { condiciones.push('p.marca_id = ?'); parametros.push(consulta.marca_id); }
  if (consulta.destacados) condiciones.push('pe.es_destacado = TRUE');
  if (consulta.promociones) condiciones.push("EXISTS (SELECT 1 FROM promociones_ecommerce pr WHERE pr.esta_activa=TRUE AND pr.codigo_cupon IS NULL AND pr.ambito='productos' AND pr.fecha_desde<=CURRENT_TIMESTAMP(3) AND pr.fecha_hasta>=CURRENT_TIMESTAMP(3) AND (EXISTS (SELECT 1 FROM promociones_ecommerce_productos pp WHERE pp.promocion_id=pr.id AND pp.producto_id=p.id) OR EXISTS (SELECT 1 FROM promociones_ecommerce_categorias pc WHERE pc.promocion_id=pr.id AND pc.categoria_id=p.categoria_id)))");
  return { donde: `WHERE ${condiciones.join(' AND ')}`, parametros };
}

export async function listarProductosOnline(consulta, admin = false) {
  const { donde, parametros } = condicionesProductos(consulta, admin); const offset = (consulta.pagina - 1) * consulta.limite;
  const base = `FROM productos p LEFT JOIN productos_ecommerce pe ON pe.producto_id=p.id JOIN categorias c ON c.id=p.categoria_id LEFT JOIN marcas m ON m.id=p.marca_id LEFT JOIN existencias e ON e.producto_id=p.id LEFT JOIN ubicaciones_stock u ON u.id=e.ubicacion_id AND u.codigo='LOCAL_PRINCIPAL' ${donde}`;
  const orden = admin ? 'ORDER BY (GREATEST(0,COALESCE(e.cantidad,0)-COALESCE(e.cantidad_reservada,0)-COALESCE(pe.stock_seguridad,0)) > 0) DESC, p.nombre' : 'ORDER BY pe.es_destacado DESC, pe.orden_destacado, p.nombre';
  const [[filas], [conteo]] = await Promise.all([
    baseDatos.query(`SELECT p.id, COALESCE(pe.nombre_online,p.nombre) nombre, p.nombre nombre_interno, COALESCE(pe.descripcion_online,p.descripcion) descripcion, c.id categoria_id, c.nombre categoria, m.id marca_id, m.nombre marca, p.es_pesable, p.imagen_url, COALESCE(pe.precio_online,p.precio_venta) precio, p.precio_venta, COALESCE(pe.stock_seguridad,0) stock_seguridad, GREATEST(0,COALESCE(e.cantidad,0)-COALESCE(e.cantidad_reservada,0)-COALESCE(pe.stock_seguridad,0)) disponible_online, COALESCE(pe.esta_publicado,FALSE) esta_publicado, COALESCE(pe.es_destacado,FALSE) es_destacado, COALESCE(pe.permite_sustitucion,TRUE) permite_sustitucion, COALESCE(pe.permite_retiro,TRUE) permite_retiro, COALESCE(pe.permite_envio,TRUE) permite_envio, pe.cantidad_maxima_pedido, pe.orden_destacado, COALESCE((SELECT ROUND(AVG(v.puntuacion),1) FROM valoraciones_ecommerce v WHERE v.producto_id=p.id),0) valoracion_promedio, (SELECT COUNT(*) FROM valoraciones_ecommerce v WHERE v.producto_id=p.id) valoraciones, COALESCE((SELECT MAX(CASE WHEN pr.tipo='precio_fijo' THEN GREATEST(0,(COALESCE(pe.precio_online,p.precio_venta)-pr.precio_fijo)*100/NULLIF(COALESCE(pe.precio_online,p.precio_venta),0)) ELSE pr.porcentaje END) FROM promociones_ecommerce pr WHERE pr.esta_activa=TRUE AND pr.codigo_cupon IS NULL AND pr.ambito='productos' AND pr.fecha_desde<=CURRENT_TIMESTAMP(3) AND pr.fecha_hasta>=CURRENT_TIMESTAMP(3) AND (EXISTS (SELECT 1 FROM promociones_ecommerce_productos pp WHERE pp.promocion_id=pr.id AND pp.producto_id=p.id) OR EXISTS (SELECT 1 FROM promociones_ecommerce_categorias pc WHERE pc.promocion_id=pr.id AND pc.categoria_id=p.categoria_id))),0) descuento_porcentaje ${base} ${orden} LIMIT ? OFFSET ?`, [...parametros, consulta.limite, offset]),
    baseDatos.query(`SELECT COUNT(DISTINCT p.id) total ${base}`, parametros),
  ]);
  return { datos: filas, total: Number(conteo[0].total), pagina: consulta.pagina, limite: consulta.limite };
}

export async function actualizarProductoOnline(productoId, datos) {
  const conexion = await baseDatos.getConnection();
  try { await conexion.beginTransaction();
    await conexion.query(`INSERT INTO productos_ecommerce (producto_id,esta_publicado,nombre_online,descripcion_online,precio_online,stock_seguridad,cantidad_maxima_pedido,permite_sustitucion,permite_retiro,permite_envio,es_destacado,orden_destacado) VALUES (?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE esta_publicado=VALUES(esta_publicado),nombre_online=VALUES(nombre_online),descripcion_online=VALUES(descripcion_online),precio_online=VALUES(precio_online),stock_seguridad=VALUES(stock_seguridad),cantidad_maxima_pedido=VALUES(cantidad_maxima_pedido),permite_sustitucion=VALUES(permite_sustitucion),permite_retiro=VALUES(permite_retiro),permite_envio=VALUES(permite_envio),es_destacado=VALUES(es_destacado),orden_destacado=VALUES(orden_destacado)`, [productoId,datos.esta_publicado,nulo(datos.nombre_online),nulo(datos.descripcion_online),nulo(datos.precio_online),datos.stock_seguridad,nulo(datos.cantidad_maxima_pedido),datos.permite_sustitucion,datos.permite_retiro,datos.permite_envio,datos.es_destacado,datos.orden_destacado]);
    await conexion.query('DELETE FROM productos_ecommerce_imagenes WHERE producto_id=?',[productoId]);
    for (const imagen of datos.imagenes) await conexion.query('INSERT INTO productos_ecommerce_imagenes (producto_id,url,texto_alternativo,orden) VALUES (?,?,?,?)',[productoId,imagen.url,nulo(imagen.texto_alternativo),imagen.orden]);
    await conexion.commit(); return { id: productoId };
  } catch(error) { await conexion.rollback(); throw error; } finally { conexion.release(); }
}

export async function referenciasPromociones() { const [[categorias],[productos]]=await Promise.all([baseDatos.query('SELECT id,nombre FROM categorias WHERE esta_activa=TRUE ORDER BY nombre'),baseDatos.query(`SELECT p.id,p.nombre,c.nombre categoria FROM productos p JOIN categorias c ON c.id=p.categoria_id JOIN productos_ecommerce pe ON pe.producto_id=p.id AND pe.esta_publicado=TRUE WHERE p.esta_activo=TRUE ORDER BY p.nombre`)]);return{categorias,productos}; }
export async function listarPromociones(soloVigentes = false) { const [filas] = await baseDatos.query(`SELECT p.*,
  (SELECT GROUP_CONCAT(pp.producto_id ORDER BY pp.producto_id) FROM promociones_ecommerce_productos pp WHERE pp.promocion_id=p.id) productos,
  (SELECT GROUP_CONCAT(pc.categoria_id ORDER BY pc.categoria_id) FROM promociones_ecommerce_categorias pc WHERE pc.promocion_id=p.id) categorias
  FROM promociones_ecommerce p ${soloVigentes ? 'WHERE p.esta_activa=TRUE AND p.fecha_desde<=CURRENT_TIMESTAMP(3) AND p.fecha_hasta>=CURRENT_TIMESTAMP(3)' : ''} ORDER BY p.fecha_desde DESC`); return filas.map((fila)=>({...fila,productos:fila.productos?fila.productos.split(',').map(Number):[],categorias:fila.categorias?fila.categorias.split(',').map(Number):[]})); }
export async function guardarPromocion(id, datos) {
  const conexion=await baseDatos.getConnection(); try { await conexion.beginTransaction();
    const campos=['nombre','descripcion','tipo','ambito','porcentaje','precio_fijo','codigo_cupon','monto_minimo','descuento_maximo','fecha_desde','fecha_hasta','es_acumulable','es_destacada','aplica_supermercado','esta_activa']; const valores=campos.map(c=>nulo(datos[c]));
    let promocionId=id; if(id) await conexion.query(`UPDATE promociones_ecommerce SET ${campos.map(c=>`${c}=?`).join(',')} WHERE id=?`,[...valores,id]); else { const [r]=await conexion.query(`INSERT INTO promociones_ecommerce (${campos.join(',')}) VALUES (${campos.map(()=>'?').join(',')})`,valores); promocionId=r.insertId; }
    await conexion.query('DELETE FROM promociones_ecommerce_productos WHERE promocion_id=?',[promocionId]); for(const productoId of datos.productos) await conexion.query('INSERT INTO promociones_ecommerce_productos (promocion_id,producto_id) VALUES (?,?)',[promocionId,productoId]);
    await conexion.query('DELETE FROM promociones_ecommerce_categorias WHERE promocion_id=?',[promocionId]); for(const categoriaId of datos.categorias) await conexion.query('INSERT INTO promociones_ecommerce_categorias (promocion_id,categoria_id) VALUES (?,?)',[promocionId,categoriaId]);
    await conexion.commit(); return {id:promocionId};
  } catch(error){await conexion.rollback();throw error;} finally{conexion.release();}
}

export async function registrarClienteOnline(datos) {
  const conexion=await baseDatos.getConnection(); try { await conexion.beginTransaction();
    const [[existente]]=await conexion.query('SELECT cliente_id FROM clientes_ecommerce WHERE correo=? FOR UPDATE',[datos.correo.toLowerCase()]); if(existente) throw errorPublico('Ya existe una cuenta con ese correo');
    const [cliente]=await conexion.query('INSERT INTO clientes (nombre,telefono,correo_electronico) VALUES (?,?,?)',[datos.nombre,datos.telefono,datos.correo.toLowerCase()]);
    await conexion.query('INSERT INTO clientes_ecommerce (cliente_id,correo,clave_hash,acepta_promociones) VALUES (?,?,?,?)',[cliente.insertId,datos.correo.toLowerCase(),await bcrypt.hash(datos.clave,12),datos.acepta_promociones]);
    await conexion.commit(); return {token:crearTokenCliente(cliente.insertId),cliente:{id:cliente.insertId,nombre:datos.nombre,correo:datos.correo.toLowerCase()}};
  } catch(error){await conexion.rollback();throw error;} finally{conexion.release();}
}
export async function accederClienteOnline(datos) { const [[fila]]=await baseDatos.query('SELECT ce.cliente_id,ce.clave_hash,c.nombre,ce.correo FROM clientes_ecommerce ce JOIN clientes c ON c.id=ce.cliente_id WHERE ce.correo=? AND c.esta_activo=TRUE',[datos.correo.toLowerCase()]); if(!fila||!await bcrypt.compare(datos.clave,fila.clave_hash)) throw errorPublico('Correo o contraseña incorrectos','ACCESO'); await baseDatos.query('UPDATE clientes_ecommerce SET ultimo_acceso=CURRENT_TIMESTAMP(3) WHERE cliente_id=?',[fila.cliente_id]); return {token:crearTokenCliente(fila.cliente_id),cliente:{id:fila.cliente_id,nombre:fila.nombre,correo:fila.correo}}; }
export async function perfilClienteOnline(clienteId) { const [[cliente]]=await baseDatos.query('SELECT c.id,c.nombre,c.telefono,ce.correo,ce.acepta_promociones FROM clientes c JOIN clientes_ecommerce ce ON ce.cliente_id=c.id WHERE c.id=?',[clienteId]); if(!cliente)return null; const [direcciones]=await baseDatos.query('SELECT * FROM direcciones_clientes WHERE cliente_id=? AND esta_activa=TRUE ORDER BY es_principal DESC,id',[clienteId]); return {...cliente,direcciones}; }
