export async function listarFavoritosCliente(clienteId) { const [filas]=await baseDatos.query(`SELECT p.id,COALESCE(pe.nombre_online,p.nombre) nombre,p.imagen_url,COALESCE(pe.precio_online,p.precio_venta) precio,GREATEST(0,COALESCE(e.cantidad,0)-COALESCE(e.cantidad_reservada,0)-COALESCE(pe.stock_seguridad,0)) disponible_online,pe.cantidad_maxima_pedido,COALESCE((SELECT MAX(CASE WHEN pr.tipo='precio_fijo' THEN GREATEST(0,(COALESCE(pe.precio_online,p.precio_venta)-pr.precio_fijo)*100/NULLIF(COALESCE(pe.precio_online,p.precio_venta),0)) ELSE pr.porcentaje END) FROM promociones_ecommerce pr WHERE pr.esta_activa=TRUE AND pr.codigo_cupon IS NULL AND pr.ambito='productos' AND pr.fecha_desde<=CURRENT_TIMESTAMP(3) AND pr.fecha_hasta>=CURRENT_TIMESTAMP(3) AND (EXISTS (SELECT 1 FROM promociones_ecommerce_productos pp WHERE pp.promocion_id=pr.id AND pp.producto_id=p.id) OR EXISTS (SELECT 1 FROM promociones_ecommerce_categorias pc WHERE pc.promocion_id=pr.id AND pc.categoria_id=p.categoria_id))),0) descuento_porcentaje FROM favoritos_ecommerce f JOIN productos p ON p.id=f.producto_id JOIN productos_ecommerce pe ON pe.producto_id=p.id AND pe.esta_publicado=TRUE LEFT JOIN existencias e ON e.producto_id=p.id LEFT JOIN ubicaciones_stock u ON u.id=e.ubicacion_id AND u.codigo='LOCAL_PRINCIPAL' WHERE f.cliente_id=? AND p.esta_activo=TRUE ORDER BY f.fecha_creacion DESC`,[clienteId]);return filas; }
