export async function guardarDireccion(clienteId, datos) { const conexion=await baseDatos.getConnection(); try{await conexion.beginTransaction(); if(datos.es_principal)await conexion.query('UPDATE direcciones_clientes SET es_principal=FALSE WHERE cliente_id=?',[clienteId]); const [r]=await conexion.query('INSERT INTO direcciones_clientes (cliente_id,etiqueta,calle,numero,piso_departamento,localidad,codigo_postal,referencias,latitud,longitud,distancia_km,zona_entrega_id,es_principal) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)',[clienteId,datos.etiqueta,datos.calle,datos.numero,nulo(datos.piso_departamento),datos.localidad,nulo(datos.codigo_postal),nulo(datos.referencias),nulo(datos.latitud),nulo(datos.longitud),nulo(datos.distancia_km),nulo(datos.zona_entrega_id),datos.es_principal]);await conexion.commit();return{id:r.insertId};}catch(error){await conexion.rollback();throw error;}finally{conexion.release();} }

async function promocionesVigentes(conexion, cupon) { const parametros=[]; let filtro="esta_activa=TRUE AND fecha_desde<=CURRENT_TIMESTAMP(3) AND fecha_hasta>=CURRENT_TIMESTAMP(3)"; if(cupon){filtro+=' AND (codigo_cupon IS NULL OR UPPER(codigo_cupon)=UPPER(?))';parametros.push(cupon);}else filtro+=' AND codigo_cupon IS NULL'; const [promos]=await conexion.query(`SELECT * FROM promociones_ecommerce WHERE ${filtro} ORDER BY es_acumulable,porcentaje DESC`,parametros); if(cupon&&!promos.some(p=>p.codigo_cupon))throw errorPublico('El cupón no existe o no está vigente'); const ids=promos.length?promos.map(p=>p.id):[0];const [[relaciones],[relacionesCategorias]]=await Promise.all([conexion.query('SELECT promocion_id,producto_id FROM promociones_ecommerce_productos WHERE promocion_id IN (?)',[ids]),conexion.query('SELECT promocion_id,categoria_id FROM promociones_ecommerce_categorias WHERE promocion_id IN (?)',[ids])]);const mapa=new Map(),mapaCategorias=new Map();for(const r of relaciones){if(!mapa.has(r.promocion_id))mapa.set(r.promocion_id,new Set());mapa.get(r.promocion_id).add(Number(r.producto_id));}for(const r of relacionesCategorias){if(!mapaCategorias.has(r.promocion_id))mapaCategorias.set(r.promocion_id,new Set());mapaCategorias.get(r.promocion_id).add(Number(r.categoria_id));}return promos.map(p=>({...p,productos:mapa.get(p.id)||new Set(),categorias:mapaCategorias.get(p.id)||new Set()})); }

export async function cotizarCarrito(datos) {
  const promociones=await promocionesVigentes(baseDatos,datos.cupon_codigo);const detalles=[];let subtotal=0,descuentoProductos=0;
  for(const item of datos.items){const [[p]]=await baseDatos.query(`SELECT p.id,p.categoria_id,COALESCE(pe.nombre_online,p.nombre) nombre,COALESCE(pe.precio_online,p.precio_venta) precio,pe.stock_seguridad,pe.cantidad_maxima_pedido,e.cantidad,e.cantidad_reservada FROM productos p JOIN productos_ecommerce pe ON pe.producto_id=p.id AND pe.esta_publicado=TRUE JOIN existencias e ON e.producto_id=p.id JOIN ubicaciones_stock u ON u.id=e.ubicacion_id AND u.codigo='LOCAL_PRINCIPAL' WHERE p.id=? AND p.esta_activo=TRUE`,[item.producto_id]);if(!p)throw errorPublico('Uno de los productos ya no está disponible');const disponible=Number(p.cantidad)-Number(p.cantidad_reservada)-Number(p.stock_seguridad);if(item.cantidad>disponible+0.0001)throw errorPublico(`No hay stock suficiente de ${p.nombre}`);if(p.cantidad_maxima_pedido&&item.cantidad>Number(p.cantidad_maxima_pedido))throw errorPublico(`${p.nombre} supera el máximo permitido`);const precio=Number(p.precio);let descuentoUnitario=0;for(const promo of promociones.filter(x=>x.ambito==='productos'&&(x.productos.has(Number(p.id))||x.categorias.has(Number(p.categoria_id))))){const candidato=promo.tipo==='precio_fijo'?Math.max(0,precio-Number(promo.precio_fijo)):precio*Number(promo.porcentaje||0)/100;if(candidato>descuentoUnitario)descuentoUnitario=candidato;if(!promo.es_acumulable)break;}const bruto=redondear(precio*item.cantidad),descuentoProducto=redondear(Math.min(bruto,descuentoUnitario*item.cantidad));subtotal+=bruto;descuentoProductos+=descuentoProducto;detalles.push({producto_id:p.id,nombre:p.nombre,cantidad:item.cantidad,precio_unitario:precio,descuento_producto:descuentoProducto,precio_promocional_unitario:redondear(precio-descuentoUnitario),subtotal_promocional:redondear(bruto-descuentoProducto)});}
  subtotal=redondear(subtotal);descuentoProductos=redondear(descuentoProductos);let descuentoPedido=0;for(const promo of promociones.filter(x=>x.ambito==='pedido'&&subtotal>=Number(x.monto_minimo))){let descuento=promo.tipo==='cupon_fijo'?Number(promo.precio_fijo||0):(subtotal-descuentoProductos-descuentoPedido)*Number(promo.porcentaje||0)/100;if(promo.descuento_maximo)descuento=Math.min(descuento,Number(promo.descuento_maximo));descuentoPedido=redondear(descuentoPedido+descuento);if(!promo.es_acumulable)break;}return{detalles,subtotal,descuento_productos:descuentoProductos,subtotal_promocional:redondear(subtotal-descuentoProductos),descuento_pedido:descuentoPedido,total_productos:redondear(subtotal-descuentoProductos-descuentoPedido),envio_gratis_promocion:promociones.some((p)=>p.tipo==='envio_gratis'&&subtotal>=Number(p.monto_minimo))};
}

export async function crearPedido(datos) {
  const conexion=await baseDatos.getConnection(); try{await conexion.beginTransaction();
    const [[config]]=await conexion.query('SELECT * FROM configuracion_ecommerce WHERE id=1 FOR UPDATE'); if(!config.esta_activa)throw errorPublico('La tienda online no está recibiendo pedidos');
    if(datos.modalidad_entrega==='envio'&&!config.permite_envio)throw errorPublico('Los envíos no están habilitados'); if(datos.modalidad_entrega==='retiro'&&!config.permite_retiro)throw errorPublico('El retiro no está habilitado');
    if(datos.medio_pago==='efectivo'&&!config.permite_efectivo||datos.medio_pago==='transferencia'&&!config.permite_transferencia||datos.medio_pago==='mercado_pago'&&!config.permite_mercado_pago)throw errorPublico('El medio de pago no está habilitado');
    let zona=null,costoEnvio=0;if(datos.modalidad_entrega==='envio'){if(!datos.direccion)throw errorPublico('Ingresá la dirección de entrega');const distanciaRuta=await calcularDistanciaPorCalles({latitud:config.latitud_origen,longitud:config.longitud_origen},datos.direccion);datos.direccion.distancia_km=distanciaRuta;if(distanciaRuta>Number(config.distancia_maxima_km))throw errorPublico(`La dirección supera el máximo de ${config.distancia_maxima_km} km por calles`);[[zona]]=await conexion.query('SELECT * FROM zonas_entrega WHERE esta_activa=TRUE AND localidad=? AND ?>=distancia_desde_km AND ?<=distancia_hasta_km ORDER BY distancia_hasta_km LIMIT 1',[datos.direccion.localidad,distanciaRuta,distanciaRuta]);if(!zona)throw errorPublico('La dirección no pertenece a una zona de entrega habilitada');datos.direccion.zona_entrega_id=zona.id;costoEnvio=Number(zona.costo)||Number(config.costo_envio_base)+Number(config.costo_por_km)*distanciaRuta;}
    const clienteId=obtenerClienteToken(datos.cliente_token); const promociones=await promocionesVigentes(conexion,datos.cupon_codigo); const detalles=[];let subtotal=0,descuento=0;
    for(const item of datos.items){const [[p]]=await conexion.query(`SELECT p.id,p.nombre,p.categoria_id,p.precio_costo,p.es_pesable,COALESCE(pe.nombre_online,p.nombre) nombre_online,COALESCE(pe.precio_online,p.precio_venta) precio,pe.stock_seguridad,pe.cantidad_maxima_pedido,pe.permite_sustitucion,pe.permite_retiro,pe.permite_envio,e.ubicacion_id,e.cantidad,e.cantidad_reservada FROM productos p JOIN productos_ecommerce pe ON pe.producto_id=p.id AND pe.esta_publicado=TRUE JOIN existencias e ON e.producto_id=p.id JOIN ubicaciones_stock u ON u.id=e.ubicacion_id AND u.codigo='LOCAL_PRINCIPAL' WHERE p.id=? AND p.esta_activo=TRUE FOR UPDATE`,[item.producto_id]);if(!p)throw errorPublico('Uno de los productos ya no está disponible');if(datos.modalidad_entrega==='envio'&&!p.permite_envio||datos.modalidad_entrega==='retiro'&&!p.permite_retiro)throw errorPublico(`${p.nombre_online} no admite esta modalidad`);if(p.cantidad_maxima_pedido&&item.cantidad>Number(p.cantidad_maxima_pedido))throw errorPublico(`${p.nombre_online} supera el máximo permitido`);const disponible=Number(p.cantidad)-Number(p.cantidad_reservada)-Number(p.stock_seguridad);if(item.cantidad>disponible+0.0001)throw errorPublico(`No hay stock suficiente de ${p.nombre_online}`);let precio=Number(p.precio),desc=0;for(const promo of promociones.filter(x=>x.ambito==='productos'&&(x.productos.has(Number(p.id))||x.categorias.has(Number(p.categoria_id))))){const candidato=promo.tipo==='precio_fijo'?Math.max(0,precio-Number(promo.precio_fijo)):precio*Number(promo.porcentaje||0)/100;if(candidato>desc)desc=candidato;if(!promo.es_acumulable)break;}const bruto=precio*item.cantidad;const descLinea=Math.min(bruto,desc*item.cantidad);subtotal+=bruto;descuento+=descLinea;detalles.push({...p,cantidad:item.cantidad,precio,descuento:descLinea,subtotal:bruto-descLinea});}
    const descuentoAntesPedido=descuento;
    for(const promo of promociones.filter(x=>x.ambito==='pedido'&&subtotal>=Number(x.monto_minimo))){let d=promo.tipo==='cupon_fijo'?Number(promo.precio_fijo||0):(subtotal-descuento)*Number(promo.porcentaje||0)/100;if(promo.descuento_maximo)d=Math.min(d,Number(promo.descuento_maximo));descuento+=d;if(!promo.es_acumulable)break;}
    const descuentoPedido=redondear(descuento-descuentoAntesPedido);if(descuentoPedido>0){const basePedido=detalles.reduce((s,d)=>s+d.subtotal,0);let restante=descuentoPedido;detalles.forEach((d,i)=>{const proporcion=i===detalles.length-1?restante:redondear(descuentoPedido*d.subtotal/basePedido);d.descuento=redondear(d.descuento+proporcion);d.subtotal=redondear(d.subtotal-proporcion);restante=redondear(restante-proporcion);});}
    if(promociones.some(x=>x.tipo==='envio_gratis'&&subtotal>=Number(x.monto_minimo))||(config.envio_gratis_desde&&subtotal-descuento>=Number(config.envio_gratis_desde)))costoEnvio=0;
    const minimo=Math.max(Number(config.pedido_minimo),Number(zona?.pedido_minimo||0));if(subtotal-descuento<minimo)throw errorPublico(`El pedido mínimo es $ ${minimo.toLocaleString('es-AR')}`);const total=redondear(subtotal-descuento+costoEnvio);const codigo=randomBytes(6).toString('hex').toUpperCase();const reservaHasta=new Date(Date.now()+Number(config.minutos_reserva)*60000);
    const direccion=datos.direccion?`${datos.direccion.calle} ${datos.direccion.numero}${datos.direccion.piso_departamento?`, ${datos.direccion.piso_departamento}`:''}`:null;
    const [pedido]=await conexion.query(`INSERT INTO pedidos_ecommerce (codigo,cliente_id,estado,estado_pago,modalidad_entrega,medio_pago,nombre_cliente,correo_cliente,telefono_cliente,direccion_cliente,localidad_cliente,latitud_entrega,longitud_entrega,distancia_km,zona_entrega_id,franja_entrega_id,fecha_entrega,acepta_sustituciones,observaciones,subtotal,descuento,costo_envio,total,cupon_codigo,reserva_hasta) VALUES (?,?, 'pendiente_pago','pendiente',?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`,[codigo,clienteId||null,datos.modalidad_entrega,datos.medio_pago,datos.nombre_cliente,datos.correo_cliente.toLowerCase(),datos.telefono_cliente,direccion,datos.direccion?.localidad||null,nulo(datos.direccion?.latitud),nulo(datos.direccion?.longitud),nulo(datos.direccion?.distancia_km),zona?.id||null,nulo(datos.franja_entrega_id),nulo(datos.fecha_entrega),datos.acepta_sustituciones,nulo(datos.observaciones),redondear(subtotal),redondear(descuento),redondear(costoEnvio),total,nulo(datos.cupon_codigo),reservaHasta]);
    for(const d of detalles){await conexion.query('INSERT INTO pedidos_ecommerce_detalles (pedido_id,producto_id,nombre_producto,cantidad_solicitada,cantidad_reservada,precio_unitario,costo_unitario,descuento,subtotal) VALUES (?,?,?,?,?,?,?,?,?)',[pedido.insertId,d.id,d.nombre_online,d.cantidad,d.cantidad,d.precio,d.precio_costo,d.descuento,d.subtotal]);await conexion.query('UPDATE existencias SET cantidad_reservada=cantidad_reservada+? WHERE producto_id=? AND ubicacion_id=?',[d.cantidad,d.id,d.ubicacion_id]);}
    await conexion.query("INSERT INTO pedidos_ecommerce_estados (pedido_id,estado_nuevo,comentario) VALUES (?,'pendiente_pago','Pedido creado desde la tienda')",[pedido.insertId]);await conexion.commit();return{id:pedido.insertId,codigo,subtotal:redondear(subtotal),descuento:redondear(descuento),costo_envio:redondear(costoEnvio),total,reserva_hasta:reservaHasta};
  }catch(error){await conexion.rollback();throw error;}finally{conexion.release();}
}

async function liberarReserva(conexion,pedidoId){const [detalles]=await conexion.query('SELECT producto_id,cantidad_reservada FROM pedidos_ecommerce_detalles WHERE pedido_id=? FOR UPDATE',[pedidoId]);for(const d of detalles){if(Number(d.cantidad_reservada)>0)await conexion.query("UPDATE existencias e JOIN ubicaciones_stock u ON u.id=e.ubicacion_id AND u.codigo='LOCAL_PRINCIPAL' SET e.cantidad_reservada=GREATEST(0,e.cantidad_reservada-?) WHERE e.producto_id=?",[d.cantidad_reservada,d.producto_id]);}await conexion.query('UPDATE pedidos_ecommerce_detalles SET cantidad_reservada=0 WHERE pedido_id=?',[pedidoId]);}
export async function expirarReservas(){const conexion=await baseDatos.getConnection();try{await conexion.beginTransaction();const [pedidos]=await conexion.query("SELECT id,estado FROM pedidos_ecommerce WHERE estado='pendiente_pago' AND reserva_hasta<CURRENT_TIMESTAMP(3) FOR UPDATE");for(const p of pedidos){await liberarReserva(conexion,p.id);await conexion.query("UPDATE pedidos_ecommerce SET estado='cancelado' WHERE id=?",[p.id]);await conexion.query("INSERT INTO pedidos_ecommerce_estados (pedido_id,estado_anterior,estado_nuevo,comentario) VALUES (?,'pendiente_pago','cancelado','Reserva vencida')",[p.id]);}await conexion.commit();return pedidos.length;}catch(e){await conexion.rollback();throw e;}finally{conexion.release();}}

export async function listarPedidos(consulta){await expirarReservas();const condiciones=[],parametros=[];if(consulta.estado){condiciones.push('p.estado=?');parametros.push(consulta.estado);}if(consulta.buscar){condiciones.push('(p.codigo LIKE ? OR p.nombre_cliente LIKE ? OR p.correo_cliente LIKE ?)');const q=`%${consulta.buscar}%`;parametros.push(q,q,q);}const donde=condiciones.length?`WHERE ${condiciones.join(' AND ')}`:'';const offset=(consulta.pagina-1)*consulta.limite;const [[datos],[conteo]]=await Promise.all([baseDatos.query(`SELECT p.*,COUNT(d.id) productos FROM pedidos_ecommerce p JOIN pedidos_ecommerce_detalles d ON d.pedido_id=p.id ${donde} GROUP BY p.id ORDER BY p.fecha_creacion DESC LIMIT ? OFFSET ?`,[...parametros,consulta.limite,offset]),baseDatos.query(`SELECT COUNT(*) total FROM pedidos_ecommerce p ${donde}`,parametros)]);return{datos,total:Number(conteo[0].total),pagina:consulta.pagina,limite:consulta.limite};}
export async function obtenerPedido(id,codigoCorreo=null){const parametros=[id];let filtro='p.id=?';if(codigoCorreo){filtro='p.codigo=? AND LOWER(p.correo_cliente)=LOWER(?)';parametros.splice(0,1,...codigoCorreo);}const [[pedido]]=await baseDatos.query(`SELECT p.*,z.nombre zona,f.nombre franja,TIME_FORMAT(f.hora_desde,'%H:%i') hora_desde,TIME_FORMAT(f.hora_hasta,'%H:%i') hora_hasta,u.nombre_usuario asignado FROM pedidos_ecommerce p LEFT JOIN zonas_entrega z ON z.id=p.zona_entrega_id LEFT JOIN franjas_entrega f ON f.id=p.franja_entrega_id LEFT JOIN usuarios u ON u.id=p.asignado_usuario_id WHERE ${filtro}`,parametros);if(!pedido)return null;const [[detalles],[estados],[pagos],[reembolsos],[devoluciones],[detallesDevoluciones]]=await Promise.all([baseDatos.query('SELECT d.*,p.nombre nombre_sustituto FROM pedidos_ecommerce_detalles d LEFT JOIN productos p ON p.id=d.producto_sustituto_id WHERE d.pedido_id=? ORDER BY d.id',[pedido.id]),baseDatos.query('SELECT e.*,u.nombre_usuario FROM pedidos_ecommerce_estados e LEFT JOIN usuarios u ON u.id=e.usuario_id WHERE e.pedido_id=? ORDER BY e.fecha_creacion,e.id',[pedido.id]),baseDatos.query('SELECT id,proveedor,estado,monto_bruto,comision,monto_neto,referencia_externa,fecha_aprobacion,fecha_creacion FROM pagos_ecommerce WHERE pedido_id=? ORDER BY id',[pedido.id]),baseDatos.query(`SELECT r.id,r.pago_id,r.monto,r.motivo,r.estado,r.referencia_externa,r.fecha_creacion,u.nombre_usuario,c.nombre cuenta_tesoreria FROM reembolsos_ecommerce r JOIN pagos_ecommerce pe ON pe.id=r.pago_id LEFT JOIN usuarios u ON u.id=r.usuario_id LEFT JOIN movimientos_tesoreria mt ON mt.id=r.movimiento_tesoreria_id LEFT JOIN cuentas_tesoreria c ON c.id=mt.cuenta_tesoreria_id WHERE pe.pedido_id=? ORDER BY r.fecha_creacion,r.id`,[pedido.id]),baseDatos.query('SELECT d.*,u.nombre_usuario FROM devoluciones_ecommerce d LEFT JOIN usuarios u ON u.id=d.usuario_id WHERE d.pedido_id=? ORDER BY d.fecha_creacion,d.id',[pedido.id]),baseDatos.query('SELECT dd.*,p.nombre producto FROM devoluciones_ecommerce_detalles dd JOIN devoluciones_ecommerce d ON d.id=dd.devolucion_id JOIN productos p ON p.id=dd.producto_id WHERE d.pedido_id=? ORDER BY dd.id',[pedido.id])]);return{...pedido,detalles,estados,pagos,reembolsos,devoluciones:devoluciones.map((devolucion)=>({...devolucion,detalles:detallesDevoluciones.filter((item)=>Number(item.devolucion_id)===Number(devolucion.id))}))};}
export async function consultarPedido(codigo,correo){return obtenerPedido(null,[codigo,correo]);}
export async function pedidosCliente(clienteId){const [filas]=await baseDatos.query('SELECT id,codigo,estado,estado_pago,modalidad_entrega,total,fecha_creacion,fecha_entregado FROM pedidos_ecommerce WHERE cliente_id=? ORDER BY fecha_creacion DESC',[clienteId]);return filas;}

export async function cambiarEstadoPedido(id,usuarioId,datos){const conexion=await baseDatos.getConnection();try{await conexion.beginTransaction();const [[p]]=await conexion.query('SELECT estado,estado_pago FROM pedidos_ecommerce WHERE id=? FOR UPDATE',[id]);if(!p)throw errorPublico('Pedido no encontrado','NO_ENCONTRADO');const permitidos={pendiente_pago:['confirmado','cancelado'],confirmado:['en_preparacion','cancelado'],en_preparacion:['listo','cancelado'],listo:['en_reparto','cancelado'],en_reparto:['cancelado']};if(!(permitidos[p.estado]||[]).includes(datos.estado))throw errorPublico(`No se puede pasar de ${p.estado} a ${datos.estado}`);if(datos.estado==='cancelado')await liberarReserva(conexion,id);const estadoPagoCancelado=datos.estado==='cancelado'&&p.estado_pago==='aprobado'?'reembolso_pendiente':p.estado_pago;await conexion.query('UPDATE pedidos_ecommerce SET estado=?,estado_pago=?,asignado_usuario_id=COALESCE(asignado_usuario_id,?) WHERE id=?',[datos.estado,estadoPagoCancelado,usuarioId,id]);await conexion.query('INSERT INTO pedidos_ecommerce_estados (pedido_id,estado_anterior,estado_nuevo,usuario_id,comentario) VALUES (?,?,?,?,?)',[id,p.estado,datos.estado,usuarioId,nulo(datos.comentario)]);await conexion.commit();return{id,estado:datos.estado};}catch(e){await conexion.rollback();throw e;}finally{conexion.release();}}
export async function prepararPedidoAnterior(id,usuarioId,datos){const conexion=await baseDatos.getConnection();try{await conexion.beginTransaction();const [[pedido]]=await conexion.query("SELECT estado,acepta_sustituciones FROM pedidos_ecommerce WHERE id=? FOR UPDATE",[id]);if(!pedido||!['confirmado','en_preparacion'].includes(pedido.estado))throw errorPublico('El pedido no está disponible para preparación');for(const item of datos.items){const [[d]]=await conexion.query('SELECT * FROM pedidos_ecommerce_detalles WHERE id=? AND pedido_id=? FOR UPDATE',[item.detalle_id,id]);if(!d)throw errorPublico('Detalle de pedido inválido');if(item.producto_sustituto_id&&!pedido.acepta_sustituciones)throw errorPublico('El cliente no aceptó sustituciones');await conexion.query("UPDATE pedidos_ecommerce_detalles SET cantidad_confirmada=?,producto_sustituto_id=?,observaciones=?,estado=? WHERE id=?",[item.cantidad_confirmada,nulo(item.producto_sustituto_id),nulo(item.observaciones),item.cantidad_confirmada>0?'preparado':'sin_stock',d.id]);}await conexion.query("UPDATE pedidos_ecommerce SET estado='listo',asignado_usuario_id=? WHERE id=?",[usuarioId,id]);await conexion.query("INSERT INTO pedidos_ecommerce_estados (pedido_id,estado_anterior,estado_nuevo,usuario_id,comentario) VALUES (?,?,'listo',?,'Preparación confirmada')",[id,pedido.estado,usuarioId]);await conexion.commit();return{id,estado:'listo'};}catch(e){await conexion.rollback();throw e;}finally{conexion.release();}}

export async function confirmarPagoPedido(id,usuarioId,datos){const conexion=await baseDatos.getConnection();try{await conexion.beginTransaction();const [[p]]=await conexion.query('SELECT total,estado,estado_pago,codigo FROM pedidos_ecommerce WHERE id=? FOR UPDATE',[id]);if(!p)throw errorPublico('Pedido no encontrado','NO_ENCONTRADO');if(['cancelado','entregado'].includes(p.estado))throw errorPublico(p.estado==='cancelado'?'No se puede cobrar un pedido cancelado. El cliente debe realizar uno nuevo.':'El pedido ya fue entregado');if(p.estado_pago==='aprobado')throw errorPublico('El pedido ya está pagado');if(Math.abs(Number(p.total)-Number(datos.monto_bruto))>0.009)throw errorPublico('El importe debe coincidir con el total del pedido');const neto=redondear(datos.monto_bruto-datos.comision);if(neto<0)throw errorPublico('La comisión no puede superar el pago');const [[cuenta]]=await conexion.query('SELECT id,nombre FROM cuentas_tesoreria WHERE id=? AND esta_activa=TRUE FOR UPDATE',[datos.cuenta_tesoreria_id]);if(!cuenta)throw errorPublico('Cuenta de Tesorería inválida');const [mov]=await conexion.query("INSERT INTO movimientos_tesoreria (cuenta_tesoreria_id,usuario_id,tipo,categoria,concepto,monto,referencia,fecha) VALUES (?,?,'ingreso','ventas_online',?,?,?,CURRENT_DATE())",[cuenta.id,usuarioId,`Cobro pedido online ${p.codigo}`,neto,datos.referencia_externa||p.codigo]);const [pago]=await conexion.query("INSERT INTO pagos_ecommerce (pedido_id,proveedor,estado,monto_bruto,comision,monto_neto,referencia_externa,idempotencia,movimiento_tesoreria_id,fecha_aprobacion) VALUES (?,?,'aprobado',?,?,?,?,?,?,CURRENT_TIMESTAMP(3))",[id,datos.proveedor,datos.monto_bruto,datos.comision,neto,nulo(datos.referencia_externa),datos.idempotencia,mov.insertId]);const estado= p.estado==='pendiente_pago'?'confirmado':p.estado;await conexion.query("UPDATE pedidos_ecommerce SET estado_pago='aprobado',estado=? WHERE id=?",[estado,id]);if(estado!==p.estado)await conexion.query("INSERT INTO pedidos_ecommerce_estados (pedido_id,estado_anterior,estado_nuevo,usuario_id,comentario) VALUES (?,? ,?,?,'Pago aprobado')",[id,p.estado,estado,usuarioId]);await conexion.commit();return{id:pago.insertId,estado_pago:'aprobado',estado,movimiento_tesoreria_id:mov.insertId};}catch(e){await conexion.rollback();throw e;}finally{conexion.release();}}

export async function entregarPedido(id,usuarioId){const conexion=await baseDatos.getConnection();try{await conexion.beginTransaction();const [[pedido]]=await conexion.query("SELECT * FROM pedidos_ecommerce WHERE id=? FOR UPDATE",[id]);if(!pedido||!['listo','en_reparto'].includes(pedido.estado))throw errorPublico('El pedido todavía no está listo');if(pedido.estado_pago!=='aprobado'&&pedido.medio_pago!=='efectivo')throw errorPublico('El pedido no tiene el pago aprobado');if(pedido.medio_pago==='efectivo'&&pedido.estado_pago!=='aprobado')throw errorPublico('Registrá primero el cobro en efectivo y su cuenta de Tesorería');const [detalles]=await conexion.query('SELECT * FROM pedidos_ecommerce_detalles WHERE pedido_id=? FOR UPDATE',[id]);const [[ubicacion]]=await conexion.query("SELECT id FROM ubicaciones_stock WHERE codigo='LOCAL_PRINCIPAL'");let total=0;for(const d of detalles){const cantidad=Number(d.cantidad_confirmada??d.cantidad_solicitada);if(cantidad<=0)continue;const productoId=d.producto_sustituto_id||d.producto_id;const [[e]]=await conexion.query('SELECT cantidad,cantidad_reservada FROM existencias WHERE producto_id=? AND ubicacion_id=? FOR UPDATE',[productoId,ubicacion.id]);if(!e||Number(e.cantidad)<cantidad)throw errorPublico(`Stock insuficiente para entregar ${d.nombre_producto}`);total+=cantidad*Number(d.precio_unitario)-Number(d.descuento);}
    const [venta]=await conexion.query("INSERT INTO ventas (sesion_caja_id,usuario_id,canal,pedido_ecommerce_id,cliente_id,estado,total,saldo_pendiente) VALUES (NULL,?,'ecommerce',?,?, 'completada',?,0)",[usuarioId,id,pedido.cliente_id,redondear(total+Number(pedido.costo_envio))]);const [mov]=await conexion.query("INSERT INTO movimientos_stock (ubicacion_id,usuario_id,tipo,motivo,referencia_tipo,referencia_id) VALUES (?,?,'salida','Entrega de pedido online','pedido_ecommerce',?)",[ubicacion.id,usuarioId,id]);for(const d of detalles){const cantidad=Number(d.cantidad_confirmada??d.cantidad_solicitada);const productoId=d.producto_sustituto_id||d.producto_id;if(cantidad<=0)continue;const [[e]]=await conexion.query('SELECT cantidad,cantidad_reservada FROM existencias WHERE producto_id=? AND ubicacion_id=? FOR UPDATE',[productoId,ubicacion.id]);const nueva=Number(e.cantidad)-cantidad;await conexion.query('INSERT INTO ventas_detalles (venta_id,producto_id,cantidad,precio_unitario,costo_unitario,subtotal) VALUES (?,?,?,?,?,?)',[venta.insertId,productoId,cantidad,d.precio_unitario,d.costo_unitario,redondear(cantidad*Number(d.precio_unitario)-Number(d.descuento))]);await conexion.query('UPDATE existencias SET cantidad=?,cantidad_reservada=GREATEST(0,cantidad_reservada-?) WHERE producto_id=? AND ubicacion_id=?',[nueva,d.cantidad_reservada,productoId,ubicacion.id]);await conexion.query('INSERT INTO movimientos_stock_detalles (movimiento_stock_id,producto_id,cantidad_anterior,variacion,cantidad_nueva,costo_unitario) VALUES (?,?,?,?,?,?)',[mov.insertId,productoId,e.cantidad,-cantidad,nueva,d.costo_unitario]);}await conexion.query("INSERT INTO ventas_pagos (venta_id,medio,monto) VALUES (?,?,?)",[venta.insertId,pedido.medio_pago,pedido.total]);await conexion.query("UPDATE pedidos_ecommerce SET estado='entregado',venta_id=?,fecha_entregado=CURRENT_TIMESTAMP(3),reserva_hasta=NULL WHERE id=?",[venta.insertId,id]);await conexion.query("INSERT INTO pedidos_ecommerce_estados (pedido_id,estado_anterior,estado_nuevo,usuario_id,comentario) VALUES (?,?,'entregado',?,'Pedido entregado y convertido en venta')",[id,pedido.estado,usuarioId]);await conexion.commit();return{id,venta_id:venta.insertId};}catch(e){await conexion.rollback();throw e;}finally{conexion.release();}}

export async function reembolsarPago(pagoId,usuarioId,datos){const conexion=await baseDatos.getConnection();try{await conexion.beginTransaction();const [[p]]=await conexion.query('SELECT pe.*,p.codigo,p.estado pedido_estado,p.total pedido_total FROM pagos_ecommerce pe JOIN pedidos_ecommerce p ON p.id=pe.pedido_id WHERE pe.id=? FOR UPDATE',[pagoId]);if(!p||p.estado!=='aprobado')throw errorPublico('Pago no disponible para reembolso');if(p.pedido_estado==='entregado')throw errorPublico('Utilizá la devolución parcial del pedido entregado');const [[sumas]]=await conexion.query("SELECT COALESCE(SUM(monto),0) reembolsado FROM reembolsos_ecommerce WHERE pago_id=? AND estado='aprobado'",[pagoId]);const saldoPagado=Number(p.monto_bruto)-Number(sumas.reembolsado);const maximo=p.pedido_estado==='cancelado'?saldoPagado:Math.max(0,saldoPagado-Number(p.pedido_total));if(datos.monto>maximo+0.009)throw errorPublico('El reembolso supera el importe pendiente autorizado');if(maximo<0.01)throw errorPublico('El pedido no tiene un reintegro pendiente');const [[cuenta]]=await conexion.query('SELECT id,COALESCE(saldo_inicial,0)+(SELECT COALESCE(SUM(IF(tipo=\'ingreso\',monto,-monto)),0) FROM movimientos_tesoreria WHERE cuenta_tesoreria_id=cuentas_tesoreria.id) saldo FROM cuentas_tesoreria WHERE id=? FOR UPDATE',[datos.cuenta_tesoreria_id]);if(!cuenta||Number(cuenta.saldo)<datos.monto)throw errorPublico('La cuenta no tiene saldo suficiente');const [mov]=await conexion.query("INSERT INTO movimientos_tesoreria (cuenta_tesoreria_id,usuario_id,tipo,categoria,concepto,monto,referencia,fecha) VALUES (?,?,'egreso','reembolso_online',?,?,?,CURRENT_DATE())",[cuenta.id,usuarioId,`Reembolso pedido ${p.codigo}`,datos.monto,datos.referencia_externa||p.codigo]);const [r]=await conexion.query("INSERT INTO reembolsos_ecommerce (pago_id,usuario_id,monto,motivo,estado,referencia_externa,movimiento_tesoreria_id) VALUES (?,?,?,?,'aprobado',?,?)",[pagoId,usuarioId,datos.monto,datos.motivo,nulo(datos.referencia_externa),mov.insertId]);const total=Number(sumas.reembolsado)+datos.monto;const saldoPosterior=Number(p.monto_bruto)-total;const estadoPago=p.pedido_estado==='cancelado'?(saldoPosterior<0.01?'reembolsado':'reembolso_parcial'):(Math.abs(saldoPosterior-Number(p.pedido_total))<0.01?'aprobado':'reembolso_parcial');await conexion.query('UPDATE pedidos_ecommerce SET estado_pago=? WHERE id=?',[estadoPago,p.pedido_id]);await conexion.commit();return{id:r.insertId,movimiento_tesoreria_id:mov.insertId};}catch(e){await conexion.rollback();throw e;}finally{conexion.release();}}

export async function devolverItemsPedido(pedidoId, usuarioId, datos) {
  const conexion = await baseDatos.getConnection();
  try {
    await conexion.beginTransaction();
    const [[pedido]] = await conexion.query("SELECT id,codigo,estado,venta_id FROM pedidos_ecommerce WHERE id=? FOR UPDATE", [pedidoId]);
    if (!pedido || pedido.estado !== 'entregado' || !pedido.venta_id) throw errorPublico('El pedido todavía no fue entregado');
    const [[pago]] = await conexion.query("SELECT * FROM pagos_ecommerce WHERE pedido_id=? AND estado='aprobado' ORDER BY id LIMIT 1 FOR UPDATE", [pedidoId]);
    if (!pago) throw errorPublico('El pedido no tiene un pago aprobado');
    const [[reembolsado]] = await conexion.query("SELECT COALESCE(SUM(monto),0) total FROM reembolsos_ecommerce WHERE pago_id=? AND estado='aprobado'", [pago.id]);
    const detalles = [];
    let total = 0;
    for (const item of datos.items) {
      const [[detalle]] = await conexion.query(`SELECT d.id,d.subtotal,d.cantidad_confirmada,d.cantidad_solicitada,COALESCE(d.producto_sustituto_id,d.producto_id) producto_id,p.nombre,COALESCE((SELECT SUM(dd.cantidad) FROM devoluciones_ecommerce_detalles dd JOIN devoluciones_ecommerce de ON de.id=dd.devolucion_id WHERE de.pedido_id=? AND dd.pedido_detalle_id=d.id),0) devuelto FROM pedidos_ecommerce_detalles d JOIN productos p ON p.id=COALESCE(d.producto_sustituto_id,d.producto_id) WHERE d.id=? AND d.pedido_id=? FOR UPDATE`, [pedidoId, item.detalle_id, pedidoId]);
      if (!detalle) throw errorPublico('Uno de los productos no pertenece al pedido');
      const vendido = Number(detalle.cantidad_confirmada ?? detalle.cantidad_solicitada);
      if (item.cantidad > vendido - Number(detalle.devuelto) + 0.0001) throw errorPublico(`La devolución de ${detalle.nombre} supera la cantidad disponible`);
      const precio = redondear(Number(detalle.subtotal) / vendido);
      const subtotal = redondear(precio * item.cantidad);
      total = redondear(total + subtotal);
      detalles.push({ ...item, producto_id: Number(detalle.producto_id), precio, subtotal });
    }
    const saldoPagado = Number(pago.monto_bruto) - Number(reembolsado.total);
    if (total > saldoPagado + 0.009) throw errorPublico('El reembolso supera el saldo pagado');
    const [[cuenta]] = await conexion.query("SELECT id,COALESCE(saldo_inicial,0)+(SELECT COALESCE(SUM(IF(tipo='ingreso',monto,-monto)),0) FROM movimientos_tesoreria WHERE cuenta_tesoreria_id=cuentas_tesoreria.id) saldo FROM cuentas_tesoreria WHERE id=? FOR UPDATE", [datos.cuenta_tesoreria_id]);
    if (!cuenta || Number(cuenta.saldo) < total) throw errorPublico('La cuenta no tiene saldo suficiente');
    const referencia = datos.referencia_externa || `DEV-${pedido.codigo}`;
    const [movimientoTesoreria] = await conexion.query("INSERT INTO movimientos_tesoreria (cuenta_tesoreria_id,usuario_id,tipo,categoria,concepto,monto,referencia,fecha) VALUES (?,?,'egreso','reembolso_online',?,?,?,CURRENT_DATE())", [cuenta.id, usuarioId, `Devolución parcial pedido ${pedido.codigo}`, total, referencia]);
    const [reembolso] = await conexion.query("INSERT INTO reembolsos_ecommerce (pago_id,usuario_id,monto,motivo,estado,referencia_externa,movimiento_tesoreria_id) VALUES (?,?,?,?,'aprobado',?,?)", [pago.id, usuarioId, total, datos.motivo, referencia, movimientoTesoreria.insertId]);
    const [devolucion] = await conexion.query('INSERT INTO devoluciones_ecommerce (pedido_id,venta_id,usuario_id,reembolso_id,motivo,total) VALUES (?,?,?,?,?,?)', [pedidoId, pedido.venta_id, usuarioId, reembolso.insertId, datos.motivo, total]);
    const [[ubicacion]] = await conexion.query("SELECT id FROM ubicaciones_stock WHERE codigo='LOCAL_PRINCIPAL'");
    const conStock = detalles.filter((item) => item.reintegra_stock);
    const movimientoStock = conStock.length ? await conexion.query("INSERT INTO movimientos_stock (ubicacion_id,usuario_id,tipo,motivo,referencia_tipo,referencia_id) VALUES (?,?,'cambio_devolucion',?,'devolucion_ecommerce',?)", [ubicacion.id, usuarioId, datos.motivo, devolucion.insertId]) : null;
    for (const item of detalles) {
      await conexion.query('INSERT INTO devoluciones_ecommerce_detalles (devolucion_id,pedido_detalle_id,producto_id,cantidad,precio_unitario,subtotal,reintegra_stock) VALUES (?,?,?,?,?,?,?)', [devolucion.insertId, item.detalle_id, item.producto_id, item.cantidad, item.precio, item.subtotal, item.reintegra_stock]);
      if (item.reintegra_stock) {
        const [[existencia]] = await conexion.query('SELECT cantidad FROM existencias WHERE producto_id=? AND ubicacion_id=? FOR UPDATE', [item.producto_id, ubicacion.id]);
        const anterior = Number(existencia?.cantidad || 0); const nueva = anterior + item.cantidad;
        await conexion.query('INSERT INTO existencias (producto_id,ubicacion_id,cantidad) VALUES (?,?,?) ON DUPLICATE KEY UPDATE cantidad=VALUES(cantidad)', [item.producto_id, ubicacion.id, nueva]);
        await conexion.query('INSERT INTO movimientos_stock_detalles (movimiento_stock_id,producto_id,cantidad_anterior,variacion,cantidad_nueva) VALUES (?,?,?,?,?)', [movimientoStock[0].insertId, item.producto_id, anterior, item.cantidad, nueva]);
      }
    }
    const totalReembolsado = Number(reembolsado.total) + total;
    await conexion.query('UPDATE pedidos_ecommerce SET estado_pago=? WHERE id=?', [Math.abs(totalReembolsado - Number(pago.monto_bruto)) < 0.01 ? 'reembolsado' : 'reembolso_parcial', pedidoId]);
    await conexion.commit();
    return { id: devolucion.insertId, total, reembolso_id: reembolso.insertId };
  } catch (error) { await conexion.rollback(); throw error; } finally { conexion.release(); }
}
